function bankEnsureOpen(PDO $pdo,string $owner,string $client,string $date):void{$q=$pdo->prepare('SELECT status FROM accounting_period_closures WHERE owner_id=? AND client_id=? AND period_key=?');$q->execute([$owner,$client,substr($date,0,7)]);if($q->fetchColumn()==='closed')jsonResponse(false,'Період банківської операції закритий.',[],409);}
