jsonResponse(false,'Один імпорт підтримує до 5000 операцій.',[],422);}$rawDate=trim((string)($row[$map['date']]??''));$date=preg_match('/^\d{4}-\d{2}-\d{2}$/',$rawDate)?$rawDate:(preg_match('/^\d{2}\.\d{2}\.\d{4}$/',$rawDate)?substr($rawDate,6,4).'-'.substr($rawDate,3,2).'-'.substr($rawDate,0,2):'');$rawAmount=str_replace([' ',' ',','],['','','.'],trim((string)($row[$map['amount']]??'')));if(!$date||!is_numeric($rawAmount)||!checkdate((int)substr($date,5,2),(int)substr($date,8,2),(int)substr($date,0,4))){$errors[]=['line'=>$line,'message'=>'Некоректна дата або сума'];continue;}$amount=(float)$rawAmount;$values=static fn($k)=>isset($map[$k])?mb_substr(trim((string)($row[$map[$k]]??'')),0,500):'';$rows[]=['date'=>$date,'amount'=>$amount,'direction'=>$amount>=0?'in':'out','currency'=>$values('currency')?:'UAH','counterparty'=>$values('counterparty'),'account'=>$values('account'),'purpose'=>$values('purpose'),'reference'=>$values('reference')];}fclose($fh);$_SESSION['accounting_bank_preview'][$hash]=['rows'=>$rows,'filename'=>basename($f['name'])];jsonResponse(true,'Попередній перегляд виписки сформовано.',['file_hash'=>$hash,'rows'=>$rows,'errors'=>$errors,'valid'=>count($rows),'failed'=>count($errors)]);}
